// [MEDIUM_PRIORITY] RESOURCE_SECURITY: Hash algorithm strong
// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recordingimport timber.log.Timberimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.security.MessageDigestimport javax.crypto.Cipherimport javax.crypto.SecretKeyimport javax.crypto.spec.SecretKeySpec/** * NOUS — Call Recording Engine (Module 11 v3 — Step 11.5). * * Records call audio (opt-in), encrypts it with AES-256, transcribes via * local LLM (Module 4 Whisper.cpp), and stores in encrypted local storage. * * ## v3 Accessibility Bypass (per strategy v3 §"CallRecordingEngine") * * Android 9+ blocks third-party apps from recording call audio via * `MediaRecorder.AudioSource.VOICE_CALL`. NOUS works around this using * the `NousAccessibilityService` (Module 9) which can capture audio output. * * For v1 (before Module 9 ships), recording uses `AudioRecord` with * `MediaRecorder.AudioSource.MIC` — this records from the microphone, * not the call line. Quality is lower (picks up ambient noise), but it * works on all devices without root. * * ## Privacy (per strategy v3 §"Privacy & Security") * *  - **Opt-in only** — user must explicitly say "Record this call" or *    enable auto-record in Settings. *  - **AES-256 encryption** — audio is encrypted before storage. *  - **On-device transcription** — local LLM (Whisper.cpp), no cloud. *  - **User-deletable** — "Delete all recordings" in Settings. *  - **Never synced** — recordings stay on device forever (until deleted). *  - **Transcript searchable** — "What did Mom say about the trip?" * * ## Flow * * ``` * User: "Record this call" *   ↓ * 1. AudioRecorder.startRecording() → captures audio * 2. Call ends → AudioRecorder.stopRecording() → raw audio data * 3. Aes256Encryptor.encrypt(audioData) → encrypted file * 4. TranscriptionLlm.transcribe(audioData) → transcript text (async) * 5. RecordingStore.store(CallRecording) → encrypted storage * 6. TTS: "Call recorded and transcribed." (persona-styled) * * Later: "What did Mom say about the trip?" *   ↓ * RecordingStore.searchByTranscript("trip") → finds matching recordings *   ↓ * TTS reads the transcript excerpt * ``` * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§CallRecordingEngine</a> */class CallRecordingEngine(    private val recorder: AudioRecorder,    /**     * Optional transcription LLM. When null (the default in v1), recordings     * are stored without transcripts. Brain's LLM (Module 4) is wired in v2+     * to provide actual transcription via Whisper.cpp.     */    private val transcriber: TranscriptionLlm?,    private val store: RecordingStore,    private val encryptor: Aes256Encryptor,    private val dispatcher: CoroutineDispatcher,    /**     * Optional TTS player for the legal notice ("This call is being recorded").     * When null, the legal notice is skipped (logging only). Strategy §11.5.     */    private val legalNoticePlayer: LegalNoticePlayer? = null,) {    private var currentContactName: String = "Unknown"    private var currentPhoneNumber: String = ""    private var currentCallStartMs: Long = 0    /**     * Start recording the current call.     *     * Called when the user says "Record this call" or when auto-record     * is enabled and a call connects.     *     * @param contactName the other party's name.     * @param phoneNumber the other party's phone number.     * @return true if recording started.     */    fun startRecording(contactName: String, phoneNumber: String): Boolean {        if (recorder.isRecording()) {            Timber.tag(TAG).w("Already recording — ignoring start.")            return false        }        currentContactName = contactName        currentPhoneNumber = phoneNumber        currentCallStartMs = System.currentTimeMillis()        val started = recorder.startRecording()        if (started) {            Timber.tag(TAG).i("Recording started: $contactName ($phoneNumber)")            // Play legal notice TTS (Strategy §11.5: "legal notice played at            // start if required"). In India, call recording is legal for            // personal use but the other party must be informed.            playLegalNotice()        } else {            Timber.tag(TAG).e("Failed to start recording.")        }        return started    }    /**     * Play a legal notice via TTS when recording starts.     *     * Strategy §11.5: "legal notice played at start if required".     *     * The notice is played through the speaker so the other party can hear it.     * Uses the injected [legalNoticePlayer] (a simple functional interface) to     * speak "This call is being recorded for your reference." The actual TTS     * implementation is provided by the caller via DI — typically the     * VoiceModule's TtsEngine.     */    private fun playLegalNotice() {        try {            legalNoticePlayer?.play("This call is being recorded for your reference.")            Timber.tag(TAG).i("Legal notice played.")        } catch (t: Throwable) {            Timber.tag(TAG).w(t, "Could not play legal notice TTS — continuing recording anyway.")        }    }    /**     * Stop recording and process: encrypt + transcribe + store.     *     * Called when the call ends or the user says "Stop recording".     *     * @return the stored recording ID, or null if processing failed.     */    suspend fun stopRecording(): String? = withContext(dispatcher) {        if (!recorder.isRecording()) {            Timber.tag(TAG).w("Not recording — ignoring stop.")            return@withContext null        }        val durationSeconds = recorder.getDurationSeconds()        val rawAudio = recorder.stopRecording()        if (rawAudio == null || rawAudio.isEmpty()) {            Timber.tag(TAG).e("Recording produced no audio data.")            return@withContext null        }        Timber.tag(TAG).i("Recording stopped: ${durationSeconds}s, ${rawAudio.size} bytes.")        // 1. Encrypt audio data.        val recordingId = generateRecordingId()        val encryptedPath = encryptor.encryptAndSave(rawAudio, recordingId)        if (encryptedPath == null) {            Timber.tag(TAG).e("Encryption failed.")            return@withContext null        }        // 2. Create recording entry (transcript pending).        val recording = CallRecording(            id = recordingId,            contactName = currentContactName,            phoneNumber = currentPhoneNumber,            timestampMs = currentCallStartMs,            durationSeconds = durationSeconds,            encryptedAudioPath = encryptedPath,            transcript = null,            isTranscribed = false,        )        val storedId = store.store(recording)        Timber.tag(TAG).i("Recording stored: $storedId (transcript pending).")        // 3. Transcribe asynchronously (may take 5-30s depending on duration).        val transcript = try {            if (transcriber?.isReady() == true) {                Timber.tag(TAG).d("Transcribing ${rawAudio.size} bytes...")                transcriber.transcribe(rawAudio)            } else {                Timber.tag(TAG).w("Transcription LLM not ready — skipping.")                null            }        } catch (t: Throwable) {            Timber.tag(TAG).e("Transcription failed", t)            null        }        // 4. Update with transcript.        if (transcript != null && transcript.isNotBlank()) {            val updated = recording.copy(                transcript = transcript,                isTranscribed = true,            )            store.store(updated)            Timber.tag(TAG).i("Transcript stored (${transcript.length} chars).")        }        // 5. Clear raw audio from memory.        // (rawAudio goes out of scope — GC will reclaim it.)        storedId    }    /**     * Search recordings by transcript content.     *     * "What did Mom say about the trip?" → searchByTranscript("trip")     */    suspend fun searchTranscripts(query: String, limit: Int = 10): List<CallRecording> = withContext(dispatcher) {        store.searchByTranscript(query, limit)    }    /**     * Get recent recordings (for UI history).     */    suspend fun getRecentRecordings(limit: Int = 20): List<CallRecording> = withContext(dispatcher) {        store.getRecent(limit)    }    /**     * Get a specific recording by ID.     */    suspend fun getRecording(recordingId: String): CallRecording? = withContext(dispatcher) {        store.get(recordingId)    }    /**     * Delete a recording.     */    suspend fun deleteRecording(recordingId: String): Boolean = withContext(dispatcher) {        store.delete(recordingId)    }    /**     * Delete all recordings (Settings → Privacy → Delete all recordings).     */    suspend fun deleteAllRecordings(): Int = withContext(dispatcher) {        store.deleteAll()    }    /** True if currently recording. */    fun isRecording(): Boolean = recorder.isRecording()    /** Generate a unique recording ID. */    private fun generateRecordingId(): String {        return "rec_${System.currentTimeMillis()}_${(1000..9999).random()}"    }    private companion object {        private const val TAG = "CallRecordingEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** * NOUS — AES-256 Encryptor (Module 11 v3 — Step 11.5). * * Encrypts call recording audio with AES-256 before storing on-device. * * ## Key management * * The encryption key is derived from the device's hardware-backed keystore * (Android Keystore). The key never leaves the device. If the device is * rooted, the key is still protected by the keystore's hardware isolation. * * For v1, the key is derived from a device-specific secret (Build.SERIAL + * app signing key hash). v2+ will use Android Keystore directly. */class Aes256Encryptor(    private val keyProvider: () -> ByteArray,    private val fileWriter: (ByteArray, String) -> String?,) {    /**     * Encrypt [data] and save to a file.     *     * @param data the raw audio data.     * @param recordingId the recording ID (used for filename).     * @return the file path of the encrypted file, or null if encryption failed.     */    fun encryptAndSave(data: ByteArray, recordingId: String): String? {        return try {            val keyBytes = keyProvider()            val secretKey: SecretKey = SecretKeySpec(keyBytes, "AES")            val cipher = Cipher.getInstance("AES/GCM/NoPadding")            cipher.init(Cipher.ENCRYPT_MODE, secretKey)            val encrypted = cipher.doFinal(data)            val path = fileWriter(encrypted, "recording_$recordingId.enc")            path        } catch (t: Throwable) {            Timber.tag("Aes256Encryptor").e("Encryption failed", t)            null        }    }    /**     * Decrypt a recording file.     *     * @param encryptedData the encrypted audio data.     * @return the decrypted audio data, or null if decryption failed.     */    fun decrypt(encryptedData: ByteArray): ByteArray? {        return try {            val keyBytes = keyProvider()            val secretKey: SecretKey = SecretKeySpec(keyBytes, "AES")            val cipher = Cipher.getInstance("AES/GCM/NoPadding")            cipher.init(Cipher.DECRYPT_MODE, secretKey)            cipher.doFinal(encryptedData)        } catch (t: Throwable) {            Timber.tag("Aes256Encryptor").e("Decryption failed", t)            null        }    }    companion object {        /**         * Generate a deterministic 256-bit key from a device secret.         *         * v1: uses SHA-256 of (Build.SERIAL + app signing key).         * v2+: uses Android Keystore (hardware-backed).         */        fun deriveKey(deviceSecret: String): ByteArray {            val digest = MessageDigest.getInstance("SHA-256")            return digest.digest(deviceSecret.toByteArray())        }    }}/** * NOUS — Legal Notice Player interface. * * Functional interface for playing a TTS announcement when call recording starts. * Strategy §11.5: "legal notice played at start if required". * * Implementations: *  - **Production**: wraps VoiceModule's TtsEngine to speak the notice. *  - **Tests**: NoopLegalNoticePlayer (does nothing). *  - **Null**: when not provided, legal notice is skipped (logging only). */fun interface LegalNoticePlayer {    /**     * Play [text] via TTS through the speaker.     *     * @param text the legal notice text to speak.     */    fun play(text: String)}